"""Import contract for professionally verified graph facts (never generated by LLM)."""
from datetime import date
from decimal import Decimal
from pydantic import Field,model_validator
from app.operations.contracts import Strict
class Evidence(Strict):
    id:str=Field(min_length=1,max_length=100)
    section:str=Field(min_length=1,max_length=100)
    location:str=Field(min_length=1,max_length=300)
    quote:str=Field(min_length=1,max_length=4000)
    valid_from:date
    valid_to:date|None=None
    source_url:str=Field(default='',max_length=1000)
class Drug(Strict):
    id:str=Field(min_length=1,max_length=80)
    name:str=Field(min_length=1,max_length=200)
    ingredients:list[str]=Field(min_length=1,max_length=50)
    allergens:list[str]=[]
    cost_per_mg_cny:Decimal|None=Field(default=None,ge=0)
    max_single_mg:Decimal=Field(gt=0,le=100000)
    max_daily_mg:Decimal=Field(gt=0,le=1000000)
    evidence:Evidence
class Food(Strict):
    id:str=Field(min_length=1,max_length=80)
    name:str=Field(min_length=1,max_length=200)
    ingredients:list[str]=Field(min_length=1,max_length=50)
    allergens:list[str]=Field(max_length=50)
    cost_per_100g_cny:Decimal|None=Field(default=None,ge=0)
    energy:Decimal=Field(ge=0,le=1000)
    protein:Decimal=Field(ge=0,le=100)
    sodium:Decimal=Field(ge=0,le=100000)
    evidence:Evidence|None=None
class Conflict(Strict):
    left:str
    right:str
    rule:str
    evidence:Evidence
class DiseaseConflict(Strict):
    disease:str
    ingredient:str
    rule:str
    evidence:Evidence
class Manifest(Strict):
    version:str=Field(min_length=1,max_length=100)
    demo:bool=False
    drugs:dict[str,Drug]
    foods:dict[str,Food]
    conflicts:list[Conflict]=[]
    diseases:list[str]=[]
    disease_conflicts:list[DiseaseConflict]=[]
    @model_validator(mode='after')
    def integrity(self):
        for key,item in {**self.drugs,**self.foods}.items():
            if key!=item.id:raise ValueError('目录键必须等于对象标识')
        ingredients={i for item in list(self.drugs.values())+list(self.foods.values()) for i in item.ingredients}
        for c in self.conflicts:
            if c.left not in ingredients or c.right not in ingredients:raise ValueError('冲突成分不存在')
        for c in self.disease_conflicts:
            if c.disease not in self.diseases or c.ingredient not in ingredients:raise ValueError('疾病禁忌对象不存在')
        evidence=[d.evidence for d in self.drugs.values()]+[c.evidence for c in self.conflicts]+[c.evidence for c in self.disease_conflicts]
        if not self.demo and any(f.evidence is None for f in self.foods.values()):raise ValueError('正式食物事实必须登记营养成分证据')
        evidence += [f.evidence for f in self.foods.values() if f.evidence]
        if not self.demo and any(not e.source_url.startswith(('http://','https://')) for e in evidence):raise ValueError('正式事实必须登记证据来源URL')
        if any(e.valid_to and e.valid_to<e.valid_from for e in evidence):raise ValueError('证据有效期错误')
        return self
